import os
import json
from typing import Any, Dict, List, Optional, Union

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def extract_layout(document_source: Union[str, bytes], model_id: str = "prebuilt-layout") -> Dict[str, Any]:
    """
    Extract OCR and layout elements from a document using Azure AI Document Intelligence.

    Args:
        document_source: Path to a local file, raw bytes, or a URL string.
        model_id: Document Intelligence model to use. Defaults to "prebuilt-layout".

    Returns:
        A normalized dictionary containing pages, blocks, lines, tables, and key layout elements.
    """
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise ValueError(
            "Missing Azure Document Intelligence configuration. "
            "Set AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY."
        )

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    if isinstance(document_source, bytes):
        poller = client.begin_analyze_document(model_id=model_id, body=document_source)
    elif isinstance(document_source, str) and (
        document_source.startswith("http://") or document_source.startswith("https://")
    ):
        poller = client.begin_analyze_document(model_id=model_id, url_source=document_source)
    elif isinstance(document_source, str):
        with open(document_source, "rb") as f:
            poller = client.begin_analyze_document(model_id=model_id, body=f)
    else:
        raise TypeError("document_source must be a file path, bytes, or URL string.")

    result = poller.result()

    normalized: Dict[str, Any] = {
        "model_id": model_id,
        "content": getattr(result, "content", None),
        "pages": [],
        "paragraphs": [],
        "tables": [],
        "selection_marks": [],
        "figures": [],
    }

    for page in getattr(result, "pages", []) or []:
        page_obj = {
            "page_number": getattr(page, "page_number", None),
            "width": getattr(page, "width", None),
            "height": getattr(page, "height", None),
            "unit": getattr(page, "unit", None),
            "words": [],
            "lines": [],
        }

        for word in getattr(page, "words", []) or []:
            page_obj["words"].append(
                {
                    "content": getattr(word, "content", None),
                    "confidence": getattr(word, "confidence", None),
                    "polygon": _polygon_to_list(getattr(word, "polygon", None)),
                }
            )

        for line in getattr(page, "lines", []) or []:
            page_obj["lines"].append(
                {
                    "content": getattr(line, "content", None),
                    "polygon": _polygon_to_list(getattr(line, "polygon", None)),
                }
            )

        normalized["pages"].append(page_obj)

    for paragraph in getattr(result, "paragraphs", []) or []:
        normalized["paragraphs"].append(
            {
                "content": getattr(paragraph, "content", None),
                "role": getattr(paragraph, "role", None),
                "bounding_regions": _bounding_regions_to_list(getattr(paragraph, "bounding_regions", None)),
                "spans": _spans_to_list(getattr(paragraph, "spans", None)),
            }
        )

    for table in getattr(result, "tables", []) or []:
        table_obj = {
            "row_count": getattr(table, "row_count", None),
            "column_count": getattr(table, "column_count", None),
            "cells": [],
            "bounding_regions": _bounding_regions_to_list(getattr(table, "bounding_regions", None)),
        }
        for cell in getattr(table, "cells", []) or []:
            table_obj["cells"].append(
                {
                    "row_index": getattr(cell, "row_index", None),
                    "column_index": getattr(cell, "column_index", None),
                    "row_span": getattr(cell, "row_span", None),
                    "column_span": getattr(cell, "column_span", None),
                    "content": getattr(cell, "content", None),
                    "kind": getattr(cell, "kind", None),
                    "bounding_regions": _bounding_regions_to_list(getattr(cell, "bounding_regions", None)),
                    "spans": _spans_to_list(getattr(cell, "spans", None)),
                }
            )
        normalized["tables"].append(table_obj)

    for mark in getattr(result, "selection_marks", []) or []:
        normalized["selection_marks"].append(
            {
                "state": getattr(mark, "state", None),
                "confidence": getattr(mark, "confidence", None),
                "polygon": _polygon_to_list(getattr(mark, "polygon", None)),
                "span": _spans_to_list([getattr(mark, "span", None)] if getattr(mark, "span", None) else None),
            }
        )

    for figure in getattr(result, "figures", []) or []:
        normalized["figures"].append(
            {
                "caption": getattr(figure, "caption", None),
                "bounding_regions": _bounding_regions_to_list(getattr(figure, "bounding_regions", None)),
            }
        )

    return normalized


def _polygon_to_list(polygon: Optional[Any]) -> Optional[List[float]]:
    if not polygon:
        return None
    try:
        return [float(point) for point in polygon]
    except TypeError:
        if hasattr(polygon, "__iter__"):
            return [float(getattr(point, "x", point[0])) for point in polygon]
        return None


def _bounding_regions_to_list(regions: Optional[Any]) -> List[Dict[str, Any]]:
    if not regions:
        return []
    out: List[Dict[str, Any]] = []
    for region in regions:
        out.append(
            {
                "page_number": getattr(region, "page_number", None),
                "polygon": _polygon_to_list(getattr(region, "polygon", None)),
            }
        )
    return out


def _spans_to_list(spans: Optional[Any]) -> List[Dict[str, Any]]:
    if not spans:
        return []
    out: List[Dict[str, Any]] = []
    for span in spans:
        if span is None:
            continue
        out.append(
            {
                "offset": getattr(span, "offset", None),
                "length": getattr(span, "length", None),
            }
        )
    return out
